INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('kmMM82ZWnJd', 4, '{"title":"63","description":"<p>247、病人不大便五六日，绕脐痛，烦躁，发作有时者，此有燥屎，故使不大便也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001018063,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-16T02:05:18.000Z', '2024-12-16T02:05:18.000Z', '2024-12-16T02:05:18.000Z', '247、病人不大便五六日，绕脐痛，烦躁，发作有时者，此有燥屎，故使不大便也。', '2024-12-16T02:05:18.000Z', 1, NULL, '5IGM9t76quT', 'section', 'UFtAP4FnkSC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('wCQNxQSSX6x', 4, '{"title":"64","description":"<p>248、病人烦热，汗出则解，又如疟状，丑晡所发热者，属阳明也；脉实者，宜下之；脉浮大者，宜发汗。下之与$f{大承气汤}；发汗宜$f{桂枝汤}。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001018064,"note":"","videoMemo":"","fangList":["大承气汤","桂枝汤"],"bieMing":""}}', '2024-12-16T02:05:18.000Z', '2024-12-16T02:05:18.000Z', '2024-12-16T02:05:18.000Z', '248、病人烦热，汗出则解，又如疟状，丑晡所发热者，属阳明也；脉实者，宜下之；脉浮大者，宜发汗。下之与$f{大承气汤}；发汗宜$f{桂枝汤}。', '2024-12-16T02:05:18.000Z', 1, NULL, '5IGM9t76quT', 'section', 'UFtAP4FnkSC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('EFCzYOWX4Jr', 4, '{"title":"65","description":"<p>249、大下后，六七日不大便，烦不解，腹满痛者，此有燥屎也，所以然者，本有宿食故也，宜$f{大承气汤}。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001018065,"note":"","videoMemo":"","fangList":["大承气汤"],"bieMing":""}}', '2024-12-16T02:05:18.000Z', '2024-12-16T02:05:18.000Z', '2024-12-16T02:05:18.000Z', '249、大下后，六七日不大便，烦不解，腹满痛者，此有燥屎也，所以然者，本有宿食故也，宜$f{大承气汤}。', '2024-12-16T02:05:18.000Z', 1, NULL, '5IGM9t76quT', 'section', 'UFtAP4FnkSC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('VZhbztyW5Q7', 4, '{"title":"66","description":"<p>250、病人小便不和，大便乍难乍易，时有微热，喘息不能卧者，有燥屎也，宜${大承气汤}。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001018066,"note":"","videoMemo":"","fangList":["大承气汤"],"bieMing":""}}', '2024-12-16T02:05:18.000Z', '2024-12-16T02:05:18.000Z', '2024-12-16T02:05:18.000Z', '250、病人小便不和，大便乍难乍易，时有微热，喘息不能卧者，有燥屎也，宜${大承气汤}。', '2024-12-16T02:05:18.000Z', 1, NULL, '5IGM9t76quT', 'section', 'UFtAP4FnkSC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('x7l2Dbm4EEF', 4, '{"title":"251、食谷欲呕者，属阳明也，$f{吴茱萸汤}主之","description":"<p>251、食谷欲呕者，属阳明也，$f{吴茱萸汤}主之。得汤反剧者，属上焦也，${小半夏汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001018067,"note":"","videoMemo":"","fangList":["吴茱萸汤","小半夏汤"],"bieMing":""}}', '2024-12-16T02:05:18.000Z', '2024-12-16T02:05:18.000Z', '2024-12-16T02:05:18.000Z', '251、食谷欲呕者，属阳明也，$f{吴茱萸汤}主之。得汤反剧者，属上焦也，${小半夏汤}主之。', '2024-12-16T02:05:18.000Z', 1, NULL, '5IGM9t76quT', 'section', 'UFtAP4FnkSC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('N25hBOKU9sU', 4, '{"title":"68","description":"<p>252、太阳病，寸缓，关浮，尺弱，其人发热汗出，复恶寒，不呕，但心下痞者，此以医下之。如其未下，病人不恶寒而渴者，此转属阳明也。小便数者，大便必鞕，不更衣十日，无所苦也，渴欲饮水者，少少与之，以法救之。渴而饮水多小便不利者，宜$f{五苓散}。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001018068,"note":"","videoMemo":"","fangList":["五苓散"],"bieMing":""}}', '2024-12-16T02:05:18.000Z', '2024-12-16T02:05:18.000Z', '2024-12-16T02:05:18.000Z', '252、太阳病，寸缓，关浮，尺弱，其人发热汗出，复恶寒，不呕，但心下痞者，此以医下之。如其未下，病人不恶寒而渴者，此转属阳明也。小便数者，大便必鞕，不更衣十日，无所苦也，渴欲饮水者，少少与之，以法救之。渴而饮水多小便不利者，宜$f{五苓散}。', '2024-12-16T02:05:18.000Z', 1, NULL, '5IGM9t76quT', 'section', 'UFtAP4FnkSC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('4n0tzw69uUa', 4, '{"title":"69","description":"<p>253、脉阳微而汗出少者，为自和；汗出多者，为太过；阳脉实，因发其汗，出多者，亦为太过，太过者，为阳绝于里，亡津液，大便因鞕也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001018069,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-16T02:05:18.000Z', '2024-12-16T02:05:18.000Z', '2024-12-16T02:05:18.000Z', '253、脉阳微而汗出少者，为自和；汗出多者，为太过；阳脉实，因发其汗，出多者，亦为太过，太过者，为阳绝于里，亡津液，大便因鞕也。', '2024-12-16T02:05:18.000Z', 1, NULL, '5IGM9t76quT', 'section', 'UFtAP4FnkSC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('0Ayhl5YjL05', 4, '{"title":"70","description":"<p>254、脉浮而芤，浮为阳，芤为阴，浮芤相搏，胃气生热，其阳则绝。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001018070,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-16T02:05:18.000Z', '2024-12-16T02:05:18.000Z', '2024-12-16T02:05:18.000Z', '254、脉浮而芤，浮为阳，芤为阴，浮芤相搏，胃气生热，其阳则绝。', '2024-12-16T02:05:18.000Z', 1, NULL, '5IGM9t76quT', 'section', 'UFtAP4FnkSC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('kfUrbQr4cr9', 4, '{"title":"71","description":"<p>255、趺阳脉浮而涩，浮则胃气强，涩则小便数，浮数相搏，大便则鞕，其脾为约，$f{麻子仁丸}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001018071,"note":"","videoMemo":"","fangList":["麻子仁丸"],"bieMing":""}}', '2024-12-16T02:05:18.000Z', '2024-12-16T02:05:18.000Z', '2024-12-16T02:05:18.000Z', '255、趺阳脉浮而涩，浮则胃气强，涩则小便数，浮数相搏，大便则鞕，其脾为约，$f{麻子仁丸}主之。', '2024-12-16T02:05:18.000Z', 1, NULL, '5IGM9t76quT', 'section', 'UFtAP4FnkSC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('2BPqaXqG1oN', 4, '{"title":"72","description":"<p>256、太阳病二日，发汗不解，蒸蒸发热者，属阳明也，调$f{胃承气汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001018072,"note":"","videoMemo":"","fangList":["胃承气汤"],"bieMing":""}}', '2024-12-16T02:05:18.000Z', '2024-12-16T02:05:18.000Z', '2024-12-16T02:05:18.000Z', '256、太阳病二日，发汗不解，蒸蒸发热者，属阳明也，调$f{胃承气汤}主之。', '2024-12-16T02:05:18.000Z', 1, NULL, '5IGM9t76quT', 'section', 'UFtAP4FnkSC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('C1ZFB5iM2ZZ', 4, '{"title":"257、伤寒吐后，腹胀满者，与$f{调胃承气汤}","description":"<p>257、伤寒吐后，腹胀满者，与$f{调胃承气汤}。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001018073,"note":"","videoMemo":"","fangList":["胃承气汤"],"bieMing":""}}', '2024-12-16T02:05:18.000Z', '2024-12-16T02:05:18.000Z', '2024-12-16T02:05:18.000Z', '257、伤寒吐后，腹胀满者，与$f{调胃承气汤}。', '2024-12-16T02:05:18.000Z', 1, NULL, '5IGM9t76quT', 'section', 'UFtAP4FnkSC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('c1uGvOHpAlx', 4, '{"title":"74","description":"<p>258、太阳病，若吐，若下，若发汗后，微烦，小便数，大便因鞕者，与${小承气汤}和之愈。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001018074,"note":"","videoMemo":"","fangList":["小承气汤"],"bieMing":""}}', '2024-12-16T02:05:18.000Z', '2024-12-16T02:05:18.000Z', '2024-12-16T02:05:18.000Z', '258、太阳病，若吐，若下，若发汗后，微烦，小便数，大便因鞕者，与${小承气汤}和之愈。', '2024-12-16T02:05:18.000Z', 1, NULL, '5IGM9t76quT', 'section', 'UFtAP4FnkSC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('FEnQtY1J030', 4, '{"title":"75","description":"<p>259、得病二三日，脉弱，无$n太阳柴胡}证，烦躁，心下鞕，至四五日，虽能食，以$f{小承气汤}少少与，微和之，令小安。至六日与$f{小承气汤}$q{一升}。若不大便六七日，小便少者，虽不大便，但初头鞕，后必溏，未定成鞕，攻之必溏，须小便利，屎定鞕，乃可攻之，宜$f{大承气汤}。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001018075,"note":"","videoMemo":"","fangList":["小承气汤","大承气汤"],"bieMing":""}}', '2024-12-16T02:05:18.000Z', '2024-12-16T02:05:18.000Z', '2024-12-16T02:05:18.000Z', '259、得病二三日，脉弱，无$n太阳柴胡}证，烦躁，心下鞕，至四五日，虽能食，以$f{小承气汤}少少与，微和之，令小安。至六日与$f{小承气汤}$q{一升}。若不大便六七日，小便少者，虽不大便，但初头鞕，后必溏，未定成鞕，攻之必溏，须小便利，屎定鞕，乃可攻之，宜$f{大承气汤}。', '2024-12-16T02:05:18.000Z', 1, NULL, '5IGM9t76quT', 'section', 'UFtAP4FnkSC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('kKrUpHo1pJN', 4, '{"title":"76","description":"<p>260、伤寒六七日，目中不了了，睛不和，无表里证，大便难，身微热者，此为实也，急下之，宜$f{大承气汤}。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001018076,"note":"","videoMemo":"","fangList":["大承气汤"],"bieMing":""}}', '2024-12-16T02:05:18.000Z', '2024-12-16T02:05:18.000Z', '2024-12-16T02:05:18.000Z', '260、伤寒六七日，目中不了了，睛不和，无表里证，大便难，身微热者，此为实也，急下之，宜$f{大承气汤}。', '2024-12-16T02:05:18.000Z', 1, NULL, '5IGM9t76quT', 'section', 'UFtAP4FnkSC');
