INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('eyxmKVuFc59', 4, '{"title":"80","description":"<p>264、阳明少阳合病，必下利，其脉不负者，为顺也；负者，失也。互相克责，名为负也。脉滑而数者，有宿食也，当下之，宜$f{大承气汤}。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001018080,"note":"","videoMemo":"","fangList":["大承气汤"],"bieMing":""}}', '2024-12-16T02:05:18.000Z', '2024-12-16T02:05:18.000Z', '2024-12-16T02:05:18.000Z', '264、阳明少阳合病，必下利，其脉不负者，为顺也；负者，失也。互相克责，名为负也。脉滑而数者，有宿食也，当下之，宜$f{大承气汤}。', '2024-12-16T02:05:18.000Z', 1, NULL, '5IGM9t76quT', 'section', 'UFtAP4FnkSC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('4CiITtP1Gv3', 4, '{"title":"81","description":"<p>265、病人无表里证，发热七八日，虽脉浮数者，可下之；假令已下，脉数不解，合热则消谷善饥，至六七日不大便者，有瘀血也，宜$f{抵当汤}；若脉数不解，而下利不止，必协热便脓血也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001018081,"note":"","videoMemo":"","fangList":["抵当汤"],"bieMing":""}}', '2024-12-16T02:05:18.000Z', '2024-12-16T02:05:18.000Z', '2024-12-16T02:05:18.000Z', '265、病人无表里证，发热七八日，虽脉浮数者，可下之；假令已下，脉数不解，合热则消谷善饥，至六七日不大便者，有瘀血也，宜$f{抵当汤}；若脉数不解，而下利不止，必协热便脓血也。', '2024-12-16T02:05:18.000Z', 1, NULL, '5IGM9t76quT', 'section', 'UFtAP4FnkSC');
