INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('3lVxC2HBft3', 4, '{"title":"103","description":"<p>287、问曰：阳明宿食何以别之？</p>\n<p></p>\n<p>          师曰：寸口脉浮而大，按之反涩，尺中亦微而涩，故知其有宿食也，$f{大承气汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001018103,"note":"","videoMemo":"","fangList":["大承气汤"],"bieMing":""}}', '2024-12-16T02:05:18.000Z', '2024-12-16T02:05:18.000Z', '2024-12-16T02:05:18.000Z', '287、问曰：阳明宿食何以别之？ 师曰：寸口脉浮而大，按之反涩，尺中亦微而涩，故知其有宿食也，$f{大承气汤}主之。', '2024-12-16T02:05:18.000Z', 1, NULL, '5IGM9t76quT', 'section', 'UFtAP4FnkSC');
