INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('8RQjITsip00', 4, '{"title":"4","description":"<p>296、本太阳病，不解，转入少阳者，胁下鞕满，干呕不能食，往来寒热，脉沉弦者，不可吐、下，与$f{小柴胡汤}。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001001904,"note":"","videoMemo":"","fangList":["小柴胡汤"],"bieMing":""}}', '2024-12-16T02:16:07.000Z', '2024-12-16T02:16:07.000Z', '2024-12-16T02:16:07.000Z', '296、本太阳病，不解，转入少阳者，胁下鞕满，干呕不能食，往来寒热，脉沉弦者，不可吐、下，与$f{小柴胡汤}。', '2024-12-16T02:16:07.000Z', 1, NULL, '5IGM9t76quT', 'section', 'kw7bbKT09Yb');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('2NN5D6CtatE', 4, '{"title":"5","description":"<p>297、少阳病，气上逆，今胁下痛，甚则呕逆，此为胆气不降也，$f{柴胡芍药枳实甘草汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001001905,"note":"","videoMemo":"","fangList":["柴胡芍药枳实甘草汤"],"bieMing":""}}', '2024-12-16T02:16:07.000Z', '2024-12-16T02:16:07.000Z', '2024-12-16T02:16:07.000Z', '297、少阳病，气上逆，今胁下痛，甚则呕逆，此为胆气不降也，$f{柴胡芍药枳实甘草汤}主之。', '2024-12-16T02:16:07.000Z', 1, NULL, '5IGM9t76quT', 'section', 'kw7bbKT09Yb');
