INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('jpEfbnssmzB', 4, '{"title":"4","description":"<p>307、自利不渴者，属太阴，以其脏有寒故也，当温之，宜服$n{理中}、$n{四逆}辈。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002004,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-16T03:56:18.000Z', '2024-12-16T03:56:18.000Z', '2024-12-16T03:56:18.000Z', '307、自利不渴者，属太阴，以其脏有寒故也，当温之，宜服$n{理中}、$n{四逆}辈。', '2024-12-16T03:56:18.000Z', 1, NULL, '5IGM9t76quT', 'section', 'XZHluCE3O7Q');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('E2WwFL51Cv8', 4, '{"title":"308、伤寒，脉浮而缓，手足自温者，系在太阴","description":"<p>308、伤寒，脉浮而缓，手足自温者，系在太阴。太阴当发身黄，若小便自利者，不能发黄。至七八日，虽暴烦，下利日十余行。必自止，以脾家实，腐秽当去故也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002005,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-16T03:56:18.000Z', '2024-12-16T03:56:18.000Z', '2024-12-16T03:56:18.000Z', '308、伤寒，脉浮而缓，手足自温者，系在太阴。太阴当发身黄，若小便自利者，不能发黄。至七八日，虽暴烦，下利日十余行。必自止，以脾家实，腐秽当去故也。', '2024-12-16T03:56:18.000Z', 1, NULL, '5IGM9t76quT', 'section', 'XZHluCE3O7Q');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('xy9UjaTXH9j', 4, '{"title":"6","description":"<p>309、本太阳病，医反下之，因尔腹满时痛者，属太阴也，$f{桂枝加芍药汤}主之；大实痛者，$f{桂枝加大黄汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002006,"note":"","videoMemo":"","fangList":["桂枝加大黄汤","桂枝加芍药汤"],"bieMing":""}}', '2024-12-16T03:56:18.000Z', '2024-12-16T03:56:18.000Z', '2024-12-16T03:56:18.000Z', '309、本太阳病，医反下之，因尔腹满时痛者，属太阴也，$f{桂枝加芍药汤}主之；大实痛者，$f{桂枝加大黄汤}主之。', '2024-12-16T03:56:18.000Z', 1, NULL, '5IGM9t76quT', 'section', 'XZHluCE3O7Q');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('NXj8ym9w5oj', 4, '{"title":"7","description":"<p>310、太阴病，脉弱，其人续自便利，设当行大黄芍药者，宜减之，以其人胃气弱，易动故也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002007,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-16T03:56:18.000Z', '2024-12-16T03:56:18.000Z', '2024-12-16T03:56:18.000Z', '310、太阴病，脉弱，其人续自便利，设当行大黄芍药者，宜减之，以其人胃气弱，易动故也。', '2024-12-16T03:56:18.000Z', 1, NULL, '5IGM9t76quT', 'section', 'XZHluCE3O7Q');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('oJ5YBFDchT2', 4, '{"title":"8","description":"<p>311、太阴病，大便反鞕，腹中胀满者，此脾气不转也，宜$f{白术枳实干姜白蜜汤}，若不胀满，反短气者，$f{黄芪五物汤加干姜半夏}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002008,"note":"","videoMemo":"","fangList":["白术枳实干姜白蜜汤，"],"bieMing":""}}', '2024-12-16T03:56:18.000Z', '2024-12-16T03:56:18.000Z', '2024-12-16T03:56:18.000Z', '311、太阴病，大便反鞕，腹中胀满者，此脾气不转也，宜$f{白术枳实干姜白蜜汤}，若不胀满，反短气者，$f{黄芪五物汤加干姜半夏}主之。', '2024-12-16T03:56:18.000Z', 1, NULL, '5IGM9t76quT', 'section', 'XZHluCE3O7Q');
