INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('tPIEofeOmA1', 4, '{"title":"2","description":"<p>321、少阴病，欲吐不吐，心烦，但欲寐，五六日，自利而渴者，属少阴也，虚，故饮水自救；若小便色白者，少阴病形悉具；小便白者，以下焦虚寒，不能制水，故令色白也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002102,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-16T04:01:15.000Z', '2024-12-16T04:01:15.000Z', '2024-12-16T04:01:15.000Z', '321、少阴病，欲吐不吐，心烦，但欲寐，五六日，自利而渴者，属少阴也，虚，故饮水自救；若小便色白者，少阴病形悉具；小便白者，以下焦虚寒，不能制水，故令色白也。', '2024-12-16T04:01:15.000Z', 1, NULL, '5IGM9t76quT', 'section', '6c40chGIzw0');
