INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('SD9Y6plaVpy', 4, '{"title":"371、伤寒先厥，后发热而利者，必自止；见厥，复利","description":"<p>371、伤寒先厥，后发热而利者，必自止；见厥，复利。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002206,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-16T06:55:34.000Z', '2024-12-16T06:55:34.000Z', '2024-12-16T06:55:34.000Z', '371、伤寒先厥，后发热而利者，必自止；见厥，复利。', '2024-12-16T06:55:34.000Z', 1, NULL, '5IGM9t76quT', 'section', 'FCG5O8QxL4a');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('h98RPSjc1Zm', 4, '{"title":"7","description":"<p>372、伤寒始发热六日，厥反九日而利；凡厥利者，当不能食，今反能食者，恐为除中；食以素饼，不发热者，知胃气尚在，必愈；恐暴热来出而复去也。后日脉之，其热续在者，期之旦日夜半愈。所以然者，本发热六日，厥反九日，复发热三日，并前六日亦为九日，与厥相应，故期之旦日夜半愈。后三日脉之，而脉数，其热不罢者，此为热气有余，必发痈脓也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002207,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-16T06:55:34.000Z', '2024-12-16T06:55:34.000Z', '2024-12-16T06:55:34.000Z', '372、伤寒始发热六日，厥反九日而利；凡厥利者，当不能食，今反能食者，恐为除中；食以素饼，不发热者，知胃气尚在，必愈；恐暴热来出而复去也。后日脉之，其热续在者，期之旦日夜半愈。所以然者，本发热六日，厥反九日，复发热三日，并前六日亦为九日，与厥相应，故期之旦日夜半愈。后三日脉之，而脉数，其热不罢者，此为热气有余，必发痈脓也。', '2024-12-16T06:55:34.000Z', 1, NULL, '5IGM9t76quT', 'section', 'FCG5O8QxL4a');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ezROrdlmE6G', 4, '{"title":"8","description":"<p>373、伤寒六七门，脉迟，而反与$f{黄芩汤}彻其热，脉迟为寒，今与$f{黄芩汤}复除其热，腹中应冷，今反能食，此名除中，必死。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002208,"note":"","videoMemo":"","fangList":["黄芩汤"],"bieMing":""}}', '2024-12-16T06:55:34.000Z', '2024-12-16T06:55:34.000Z', '2024-12-16T06:55:34.000Z', '373、伤寒六七门，脉迟，而反与$f{黄芩汤}彻其热，脉迟为寒，今与$f{黄芩汤}复除其热，腹中应冷，今反能食，此名除中，必死。', '2024-12-16T06:55:34.000Z', 1, NULL, '5IGM9t76quT', 'section', 'FCG5O8QxL4a');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('R9ob3akYn6k', 4, '{"title":"9","description":"<p>374、伤寒，先厥后发热，下利必自止，而反汗出，咽中痛者，其喉为痹；发热，无汗，而利必自止；若不止，必便脓血，便脓血者，其喉不痹。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002209,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-16T06:55:34.000Z', '2024-12-16T06:55:34.000Z', '2024-12-16T06:55:34.000Z', '374、伤寒，先厥后发热，下利必自止，而反汗出，咽中痛者，其喉为痹；发热，无汗，而利必自止；若不止，必便脓血，便脓血者，其喉不痹。', '2024-12-16T06:55:34.000Z', 1, NULL, '5IGM9t76quT', 'section', 'FCG5O8QxL4a');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('zZPs6f1pY82', 4, '{"title":"375、伤寒一二日，至四五日，厥者，必发热","description":"<p>375、伤寒一二日，至四五日，厥者，必发热。前热者，后必厥；厥深者，热亦深；厥微者，热亦微；厥应下之，而反发汗者，必口伤烂赤。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002210,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-16T06:55:34.000Z', '2024-12-16T06:55:34.000Z', '2024-12-16T06:55:34.000Z', '375、伤寒一二日，至四五日，厥者，必发热。前热者，后必厥；厥深者，热亦深；厥微者，热亦微；厥应下之，而反发汗者，必口伤烂赤。', '2024-12-16T06:55:34.000Z', 1, NULL, '5IGM9t76quT', 'section', 'FCG5O8QxL4a');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('UNU2Tc4Ucxc', 4, '{"title":"11","description":"<p>376、伤寒病，厥五日，热亦五日，设六日当复厥，不厥者自愈；厥终不过五日，以热五日，知自愈。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002211,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-16T06:55:34.000Z', '2024-12-16T06:55:34.000Z', '2024-12-16T06:55:34.000Z', '376、伤寒病，厥五日，热亦五日，设六日当复厥，不厥者自愈；厥终不过五日，以热五日，知自愈。', '2024-12-16T06:55:34.000Z', 1, NULL, '5IGM9t76quT', 'section', 'FCG5O8QxL4a');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('0l5NFZgz8mF', 4, '{"title":"377、凡厥者，阴阳气不相顺接，便为厥","description":"<p>377、凡厥者，阴阳气不相顺接，便为厥。厥者，手足逆冷是也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002212,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-16T06:55:34.000Z', '2024-12-16T06:55:34.000Z', '2024-12-16T06:55:34.000Z', '377、凡厥者，阴阳气不相顺接，便为厥。厥者，手足逆冷是也。', '2024-12-16T06:55:34.000Z', 1, NULL, '5IGM9t76quT', 'section', 'FCG5O8QxL4a');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('2UtG39ZPM6O', 4, '{"title":"13","description":"<p>378、伤寒，脉微而厥，至七八日，肤冷，其人躁，无暂安时者，此为脏厥，非蚘厥也。蚘厥者，其人当吐蚘，今病者静，而复时烦，此为脏寒，蚘上入其膈，故烦，须臾复止，得食而呕又烦者，蚘闻食臭出，其人当自吐蚘。蚘厥者，$f{乌梅丸}主之，又主久利。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002213,"note":"","videoMemo":"","fangList":["乌梅丸"],"bieMing":""}}', '2024-12-16T06:55:34.000Z', '2024-12-16T06:55:34.000Z', '2024-12-16T06:55:34.000Z', '378、伤寒，脉微而厥，至七八日，肤冷，其人躁，无暂安时者，此为脏厥，非蚘厥也。蚘厥者，其人当吐蚘，今病者静，而复时烦，此为脏寒，蚘上入其膈，故烦，须臾复止，得食而呕又烦者，蚘闻食臭出，其人当自吐蚘。蚘厥者，$f{乌梅丸}主之，又主久利。', '2024-12-16T06:55:34.000Z', 1, NULL, '5IGM9t76quT', 'section', 'FCG5O8QxL4a');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('F0Citz3c6M3', 4, '{"title":"14","description":"<p>379、伤寒，热少，微厥，指头寒，嘿嘿不欲食，烦躁，数日小便利色白者，此热除也，欲得食，其病为愈；若厥而呕，胸胁烦满者，其后必便血。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002214,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-16T06:55:34.000Z', '2024-12-16T06:55:34.000Z', '2024-12-16T06:55:34.000Z', '379、伤寒，热少，微厥，指头寒，嘿嘿不欲食，烦躁，数日小便利色白者，此热除也，欲得食，其病为愈；若厥而呕，胸胁烦满者，其后必便血。', '2024-12-16T06:55:34.000Z', 1, NULL, '5IGM9t76quT', 'section', 'FCG5O8QxL4a');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('LooB9Q1ClW2', 4, '{"title":"15","description":"<p>380、病者手足厥冷，不结胸，小腹满，按之痛者，此冷结在膀胱关元也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002215,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-16T06:55:34.000Z', '2024-12-16T06:55:34.000Z', '2024-12-16T06:55:34.000Z', '380、病者手足厥冷，不结胸，小腹满，按之痛者，此冷结在膀胱关元也。', '2024-12-16T06:55:34.000Z', 1, NULL, '5IGM9t76quT', 'section', 'FCG5O8QxL4a');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('qr3ahe4BZQG', 4, '{"title":"16","description":"<p>381、伤寒发热四日，厥反三日，复热四日，厥少热多者，其病当愈；四日至七日，热不除者，必便脓血。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002216,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-16T06:55:34.000Z', '2024-12-16T06:55:34.000Z', '2024-12-16T06:55:34.000Z', '381、伤寒发热四日，厥反三日，复热四日，厥少热多者，其病当愈；四日至七日，热不除者，必便脓血。', '2024-12-16T06:55:34.000Z', 1, NULL, '5IGM9t76quT', 'section', 'FCG5O8QxL4a');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('08p583JbAcp', 4, '{"title":"17","description":"<p>382、伤寒厥四日，热反三日，复厥五日，其病为进，寒多热少，阳气退，故为进也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002217,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-16T06:55:34.000Z', '2024-12-16T06:55:34.000Z', '2024-12-16T06:55:34.000Z', '382、伤寒厥四日，热反三日，复厥五日，其病为进，寒多热少，阳气退，故为进也。', '2024-12-16T06:55:34.000Z', 1, NULL, '5IGM9t76quT', 'section', 'FCG5O8QxL4a');
