INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('2Z5Yd2MLODD', 4, '{"title":"29","description":"<p>394、病人手足厥冷，脉乍紧者，邪结在胸中，心下满而烦，饥不能食者，病在胸中，当须吐之，宜$f{瓜蒂散}。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002229,"note":"","videoMemo":"","fangList":["瓜蒂散"],"bieMing":""}}', '2024-12-16T06:55:34.000Z', '2024-12-16T06:55:34.000Z', '2024-12-16T06:55:34.000Z', '394、病人手足厥冷，脉乍紧者，邪结在胸中，心下满而烦，饥不能食者，病在胸中，当须吐之，宜$f{瓜蒂散}。', '2024-12-16T06:55:34.000Z', 1, NULL, '5IGM9t76quT', 'section', 'FCG5O8QxL4a');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('AjP1Zpg1dve', 4, '{"title":"30","description":"<p>395、伤寒，厥而心下悸者，宜先治水，当服$f{茯苓甘草汤}，却治其厥，不尔水渍入胃，必作利也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002230,"note":"","videoMemo":"","fangList":["茯苓甘草汤"],"bieMing":""}}', '2024-12-16T06:55:34.000Z', '2024-12-16T06:55:34.000Z', '2024-12-16T06:55:34.000Z', '395、伤寒，厥而心下悸者，宜先治水，当服$f{茯苓甘草汤}，却治其厥，不尔水渍入胃，必作利也。', '2024-12-16T06:55:34.000Z', 1, NULL, '5IGM9t76quT', 'section', 'FCG5O8QxL4a');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('zgiX6P6dpiY', 4, '{"title":"31","description":"<p>396、伤寒六七日，大下后，寸脉沉而迟，手足厥逆，下部脉不至，咽喉不利，唾脓血，泄利不止者，为难治，$f{人参附子汤}主之；不差，复以$f{人参干姜汤}与之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002231,"note":"","videoMemo":"","fangList":["人参附子汤","人参干姜汤"],"bieMing":""}}', '2024-12-16T06:55:34.000Z', '2024-12-16T06:55:34.000Z', '2024-12-16T06:55:34.000Z', '396、伤寒六七日，大下后，寸脉沉而迟，手足厥逆，下部脉不至，咽喉不利，唾脓血，泄利不止者，为难治，$f{人参附子汤}主之；不差，复以$f{人参干姜汤}与之。', '2024-12-16T06:55:34.000Z', 1, NULL, '5IGM9t76quT', 'section', 'FCG5O8QxL4a');
