INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('GNv4RrwcQ0o', 4, '{"title":"66","description":"<p>431、病人呕，吐涎沫，心痛，若腹痛发作有时，其脉反洪大者，此虫之为病也，$f{甘草粉蜜汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002266,"note":"","videoMemo":"","fangList":["甘草粉蜜汤"],"bieMing":""}}', '2024-12-16T07:44:59.000Z', '2024-12-16T07:44:59.000Z', '2024-12-16T07:44:59.000Z', '431、病人呕，吐涎沫，心痛，若腹痛发作有时，其脉反洪大者，此虫之为病也，$f{甘草粉蜜汤}主之。', '2024-12-16T07:44:59.000Z', 1, NULL, '5IGM9t76quT', 'section', 'FCG5O8QxL4a');
