INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('yZQRYZZ4HxQ', 4, '{"title":"70","description":"<p>436、寸口脉浮而迟，浮则为虚，迟则为劳；虚则卫气不足，劳则荣气竭。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002270,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-16T07:44:59.000Z', '2024-12-16T07:44:59.000Z', '2024-12-16T07:44:59.000Z', '436、寸口脉浮而迟，浮则为虚，迟则为劳；虚则卫气不足，劳则荣气竭。', '2024-12-16T07:44:59.000Z', 1, NULL, '5IGM9t76quT', 'section', 'FCG5O8QxL4a');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('GJEy05D3ZAC', 4, '{"title":"71","description":"<p>437、趺阳脉浮而数，浮则为气，数则消谷而大坚，气盛则溲数，溲数则坚，坚数相搏，即为消渴。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002271,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-16T07:44:59.000Z', '2024-12-16T07:44:59.000Z', '2024-12-16T07:44:59.000Z', '437、趺阳脉浮而数，浮则为气，数则消谷而大坚，气盛则溲数，溲数则坚，坚数相搏，即为消渴。', '2024-12-16T07:44:59.000Z', 1, NULL, '5IGM9t76quT', 'section', 'FCG5O8QxL4a');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('R83B4IQC1Iq', 4, '{"title":"72","description":"<p>438、消渴，小便多，饮一斗，小便亦一斗者，$f{肾气丸}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002272,"note":"","videoMemo":"","fangList":["肾气丸"],"bieMing":""}}', '2024-12-16T07:44:59.000Z', '2024-12-16T07:44:59.000Z', '2024-12-16T07:44:59.000Z', '438、消渴，小便多，饮一斗，小便亦一斗者，$f{肾气丸}主之。', '2024-12-16T07:44:59.000Z', 1, NULL, '5IGM9t76quT', 'section', 'FCG5O8QxL4a');
