INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('pwqsu0EutDF', 4, '{"title":"75","description":"<p>442、小便痛閟，下如粟状，少腹弦急，痛引脐中，其名曰淋，此热结在下焦也，$f{小柴胡加茯苓汤}主之。</p>\n<p>  </p>\n<p>          $a{  “閟”}：$v{音bì，通“闭”}。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002275,"note":"","videoMemo":"","fangList":["小柴胡加茯苓汤"],"bieMing":""}}', '2024-12-16T07:44:59.000Z', '2024-12-16T07:44:59.000Z', '2024-12-16T07:44:59.000Z', '442、小便痛閟，下如粟状，少腹弦急，痛引脐中，其名曰淋，此热结在下焦也，$f{小柴胡加茯苓汤}主之。 $a{ “閟”}：$v{音bì，通“闭”}。', '2024-12-16T07:44:59.000Z', 1, NULL, '5IGM9t76quT', 'section', 'FCG5O8QxL4a');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('fz5h4Pcejm6', 4, '{"title":"1","description":"<p>1、问曰：病有霍乱者何？答曰：呕吐而利，此名霍乱。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002301,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-16T08:14:11.000Z', '2024-12-16T08:14:11.000Z', '2024-12-16T08:14:11.000Z', '1、问曰：病有霍乱者何？答曰：呕吐而利，此名霍乱。', '2024-12-16T08:14:11.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Ivl1mj3EGPu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('xEi9sxTdabF', 4, '{"title":"2","description":"<p>2、师曰：霍乱属太阴，霍乱必吐利，吐利不必尽霍乱。霍乱者，由寒热杂合混乱于中也。热气上逆故吐，寒气下注故利，其有饮食不节，壅滞于中上者，竟上则吐，下者，竟下则利，此名吐利，非霍乱也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002302,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-16T08:14:11.000Z', '2024-12-16T08:14:11.000Z', '2024-12-16T08:14:11.000Z', '2、师曰：霍乱属太阴，霍乱必吐利，吐利不必尽霍乱。霍乱者，由寒热杂合混乱于中也。热气上逆故吐，寒气下注故利，其有饮食不节，壅滞于中上者，竟上则吐，下者，竟下则利，此名吐利，非霍乱也。', '2024-12-16T08:14:11.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Ivl1mj3EGPu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('dKFsIF8z5ta', 4, '{"title":"3","description":"<p>3、问曰：病有发热，头痛，身疼，恶寒，吐利者，此属何病？</p>\n<p></p>\n<p>            答曰：此非霍乱，霍乱自吐下，今恶寒，身疼，复更发热，故知非霍乱也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002303,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-16T08:14:11.000Z', '2024-12-16T08:14:11.000Z', '2024-12-16T08:14:11.000Z', '3、问曰：病有发热，头痛，身疼，恶寒，吐利者，此属何病？ 答曰：此非霍乱，霍乱自吐下，今恶寒，身疼，复更发热，故知非霍乱也。', '2024-12-16T08:14:11.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Ivl1mj3EGPu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Rk13nait0Ki', 4, '{"title":"4、霍乱呕、吐、下利，无寒热，脉濡弱者，$f{理中汤}主之","description":"<p>4、霍乱呕、吐、下利，无寒热，脉濡弱者，$f{理中汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002304,"note":"","videoMemo":"","fangList":["理中汤"],"bieMing":""}}', '2024-12-16T08:14:11.000Z', '2024-12-16T08:14:11.000Z', '2024-12-16T08:14:11.000Z', '4、霍乱呕、吐、下利，无寒热，脉濡弱者，$f{理中汤}主之。', '2024-12-16T08:14:11.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Ivl1mj3EGPu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('WlpJuuheZ5m', 4, '{"title":"5","description":"<p>5、先吐，后利，腹中满痛，无寒热，脉濡弱而涩者，此宿食也，$f{白术茯苓半夏枳实汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002305,"note":"","videoMemo":"","fangList":["白术茯苓半夏枳实汤"],"bieMing":""}}', '2024-12-16T08:14:11.000Z', '2024-12-16T08:14:11.000Z', '2024-12-16T08:14:11.000Z', '5、先吐，后利，腹中满痛，无寒热，脉濡弱而涩者，此宿食也，$f{白术茯苓半夏枳实汤}主之。', '2024-12-16T08:14:11.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Ivl1mj3EGPu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('LszUrpWMMaa', 4, '{"title":"6","description":"<p>6、胸中满，欲吐不吐，下利时疏，无寒热，腹中绞痛，寸口脉弱而结者，此宿食在上故也，宜$f{瓜蒂散}。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002306,"note":"","videoMemo":"","fangList":["瓜蒂散"],"bieMing":""}}', '2024-12-16T08:14:11.000Z', '2024-12-16T08:14:11.000Z', '2024-12-16T08:14:11.000Z', '6、胸中满，欲吐不吐，下利时疏，无寒热，腹中绞痛，寸口脉弱而结者，此宿食在上故也，宜$f{瓜蒂散}。', '2024-12-16T08:14:11.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Ivl1mj3EGPu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('M6Zce4Rx6B5', 4, '{"title":"7","description":"<p>7、霍乱呕、吐，下利清谷，手足厥冷，脉沉而迟者，$f{四逆汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002307,"note":"","videoMemo":"","fangList":["四逆汤"],"bieMing":""}}', '2024-12-16T08:14:11.000Z', '2024-12-16T08:14:11.000Z', '2024-12-16T08:14:11.000Z', '7、霍乱呕、吐，下利清谷，手足厥冷，脉沉而迟者，$f{四逆汤}主之。', '2024-12-16T08:14:11.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Ivl1mj3EGPu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('fb02WeZA3XY', 4, '{"title":"8","description":"<p>8、吐、利，发热，脉濡弱而大者，$f{白术石膏半夏干姜汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002308,"note":"","videoMemo":"","fangList":["白术石膏半夏干姜汤"],"bieMing":""}}', '2024-12-16T08:14:11.000Z', '2024-12-16T08:14:11.000Z', '2024-12-16T08:14:11.000Z', '8、吐、利，发热，脉濡弱而大者，$f{白术石膏半夏干姜汤}主之。', '2024-12-16T08:14:11.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Ivl1mj3EGPu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('tpJAzgSL0ek', 4, '{"title":"9","description":"<p>9、呕吐甚则蚘出，下利时密时疏，身微热，手足厥冷，面色青，脉沉弦而紧者，$f{四逆加吴茱萸黄连汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002309,"note":"","videoMemo":"","fangList":["四逆加吴茱萸黄连汤"],"bieMing":""}}', '2024-12-16T08:14:11.000Z', '2024-12-16T08:14:11.000Z', '2024-12-16T08:14:11.000Z', '9、呕吐甚则蚘出，下利时密时疏，身微热，手足厥冷，面色青，脉沉弦而紧者，$f{四逆加吴茱萸黄连汤}主之。', '2024-12-16T08:14:11.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Ivl1mj3EGPu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('gexL3xkDa3g', 4, '{"title":"10","description":"<p>10、霍乱吐、利，口渴，汗出，短气，脉弱而濡者，$f{理中加人参括蒌根汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002310,"note":"","videoMemo":"","fangList":["理中加人参括蒌根汤"],"bieMing":""}}', '2024-12-16T08:14:11.000Z', '2024-12-16T08:14:11.000Z', '2024-12-16T08:14:11.000Z', '10、霍乱吐、利，口渴，汗出，短气，脉弱而濡者，$f{理中加人参括蒌根汤}主之。', '2024-12-16T08:14:11.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Ivl1mj3EGPu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('W54qsUYk8T2', 4, '{"title":"11","description":"<p>11、饮水即吐，食谷则利，脉迟而弱者，$f{理中加附子汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002311,"note":"","videoMemo":"","fangList":["理中加附子汤"],"bieMing":""}}', '2024-12-16T08:14:11.000Z', '2024-12-16T08:14:11.000Z', '2024-12-16T08:14:11.000Z', '11、饮水即吐，食谷则利，脉迟而弱者，$f{理中加附子汤}主之。', '2024-12-16T08:14:11.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Ivl1mj3EGPu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('hx7PDvYlb7W', 4, '{"title":"12","description":"<p>12、腹中胀满而痛，时时上下，痛气上则吐，痛气下则利，脉濡而涩者，$f{理中汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002312,"note":"","videoMemo":"","fangList":["理中汤"],"bieMing":""}}', '2024-12-16T08:14:11.000Z', '2024-12-16T08:14:11.000Z', '2024-12-16T08:14:11.000Z', '12、腹中胀满而痛，时时上下，痛气上则吐，痛气下则利，脉濡而涩者，$f{理中汤}主之。', '2024-12-16T08:14:11.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Ivl1mj3EGPu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('F20WQE0bG2u', 4, '{"title":"13","description":"<p>13、霍乱证，有虚实，因其人本有虚实，证随本变故也，虚者脉濡而弱，宜$f{理中汤}；实者脉急而促，宜$f{葛根黄连黄芩甘草汤}。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002313,"note":"","videoMemo":"","fangList":["理中汤","葛根黄连黄芩甘草汤"],"bieMing":""}}', '2024-12-16T08:14:11.000Z', '2024-12-16T08:14:11.000Z', '2024-12-16T08:14:11.000Z', '13、霍乱证，有虚实，因其人本有虚实，证随本变故也，虚者脉濡而弱，宜$f{理中汤}；实者脉急而促，宜$f{葛根黄连黄芩甘草汤}。', '2024-12-16T08:14:11.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Ivl1mj3EGPu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('J5mXH2fmfpA', 4, '{"title":"14","description":"<p>14、霍乱，转筋，必先其时已有寒邪留于筋间，伤其荣气，随证而发，脉当濡弱，反见弦急厥逆者，$f{理中加附子汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002314,"note":"","videoMemo":"","fangList":["理中加附子汤"],"bieMing":""}}', '2024-12-16T08:14:11.000Z', '2024-12-16T08:14:11.000Z', '2024-12-16T08:14:11.000Z', '14、霍乱，转筋，必先其时已有寒邪留于筋间，伤其荣气，随证而发，脉当濡弱，反见弦急厥逆者，$f{理中加附子汤}主之。', '2024-12-16T08:14:11.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Ivl1mj3EGPu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('JJEizCo7Tfh', 4, '{"title":"15","description":"<p>15、霍乱，已，头痛，发热，身疼痛，热多，欲饮水者，$f{五苓散}主之；寒多，不饮水者，${理中丸}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002315,"note":"","videoMemo":"","fangList":["五苓散","理中丸"],"bieMing":""}}', '2024-12-16T08:14:11.000Z', '2024-12-16T08:14:11.000Z', '2024-12-16T08:14:11.000Z', '15、霍乱，已，头痛，发热，身疼痛，热多，欲饮水者，$f{五苓散}主之；寒多，不饮水者，${理中丸}主之。', '2024-12-16T08:14:11.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Ivl1mj3EGPu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('GBxUlz2AXgl', 4, '{"title":"16","description":"<p>16、伤寒其脉微涩者，本是霍乱，今是伤寒，却四五日，至阴经上，若转入阴者，必利；若欲似大便，而反失气，仍不利者，此属阳明也，便必鞕，十三日愈。所以然者，经尽故也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002316,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-16T08:14:11.000Z', '2024-12-16T08:14:11.000Z', '2024-12-16T08:14:11.000Z', '16、伤寒其脉微涩者，本是霍乱，今是伤寒，却四五日，至阴经上，若转入阴者，必利；若欲似大便，而反失气，仍不利者，此属阳明也，便必鞕，十三日愈。所以然者，经尽故也。', '2024-12-16T08:14:11.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Ivl1mj3EGPu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('xm1qDpo4bUH', 4, '{"title":"17","description":"<p>17、下利后，便当鞕，鞕则能食者，愈；今反不能食，到后经中，颇能食，复过一经亦能食，过之一日当愈，不愈者，不属阳明也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002317,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-16T08:14:11.000Z', '2024-12-16T08:14:11.000Z', '2024-12-16T08:14:11.000Z', '17、下利后，便当鞕，鞕则能食者，愈；今反不能食，到后经中，颇能食，复过一经亦能食，过之一日当愈，不愈者，不属阳明也。', '2024-12-16T08:14:11.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Ivl1mj3EGPu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('X3vKn8amvrh', 4, '{"title":"18","description":"<p>18、伤寒脉微而复利，利自止者，亡血也，$f{四逆加人参汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002318,"note":"","videoMemo":"","fangList":["四逆加人参汤"],"bieMing":""}}', '2024-12-16T08:14:11.000Z', '2024-12-16T08:14:11.000Z', '2024-12-16T08:14:11.000Z', '18、伤寒脉微而复利，利自止者，亡血也，$f{四逆加人参汤}主之。', '2024-12-16T08:14:11.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Ivl1mj3EGPu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('K2AeGhMt4LZ', 4, '{"title":"19","description":"<p>19、吐、利止，而身痛不休者，当消息和解其外，宜$f{桂枝汤}。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002319,"note":"","videoMemo":"","fangList":["桂枝汤"],"bieMing":""}}', '2024-12-16T08:14:11.000Z', '2024-12-16T08:14:11.000Z', '2024-12-16T08:14:11.000Z', '19、吐、利止，而身痛不休者，当消息和解其外，宜$f{桂枝汤}。', '2024-12-16T08:14:11.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Ivl1mj3EGPu');
