INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('mkrIQ7Q1gl8', 4, '{"title":"7","description":"<p>7、病者身热足寒，颈项强急，恶寒，时头热，面赤目赤，独头动摇，卒口噤，背反张者，痉病也。若发其汗，寒湿相得，其表益虚，则恶寒甚，发其汗已，其脉如蛇，暴脉长大者，为欲解；其脉如故，及伏弦者，为未解。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002407,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-16T09:13:13.000Z', '2024-12-16T09:13:13.000Z', '2024-12-16T09:13:13.000Z', '7、病者身热足寒，颈项强急，恶寒，时头热，面赤目赤，独头动摇，卒口噤，背反张者，痉病也。若发其汗，寒湿相得，其表益虚，则恶寒甚，发其汗已，其脉如蛇，暴脉长大者，为欲解；其脉如故，及伏弦者，为未解。', '2024-12-16T09:13:13.000Z', 1, NULL, '5IGM9t76quT', 'section', 'kBNKud90m4z');
