INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('y64fXSpImpN', 4, '{"title":"17","description":"<p>17、伤寒差已后，更发热者，$f{小柴胡汤}主之；脉浮者，以汗解之；脉沉实者，以下解之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002417,"note":"","videoMemo":"","fangList":["小柴胡汤"],"bieMing":""}}', '2024-12-16T09:13:13.000Z', '2024-12-16T09:13:13.000Z', '2024-12-16T09:13:13.000Z', '17、伤寒差已后，更发热者，$f{小柴胡汤}主之；脉浮者，以汗解之；脉沉实者，以下解之。', '2024-12-16T09:13:13.000Z', 1, NULL, '5IGM9t76quT', 'section', 'kBNKud90m4z');
