INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('1Pugi5KB2zn', 4, '{"title":"19","description":"<p>19、大病差后，喜唾，久不了了，胸上有寒也，当以丸药温之，宜$f{理中丸}。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002419,"note":"","videoMemo":"","fangList":["理中丸"],"bieMing":""}}', '2024-12-16T09:13:13.000Z', '2024-12-16T09:13:13.000Z', '2024-12-16T09:13:13.000Z', '19、大病差后，喜唾，久不了了，胸上有寒也，当以丸药温之，宜$f{理中丸}。', '2024-12-16T09:13:13.000Z', 1, NULL, '5IGM9t76quT', 'section', 'kBNKud90m4z');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('1MRV0dyLsSr', 4, '{"title":"20","description":"<p>20、伤寒解后，虚赢少气，气逆欲吐者，$f{竹叶石膏汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002420,"note":"","videoMemo":"","fangList":["竹叶石膏汤"],"bieMing":""}}', '2024-12-16T09:13:13.000Z', '2024-12-16T09:13:13.000Z', '2024-12-16T09:13:13.000Z', '20、伤寒解后，虚赢少气，气逆欲吐者，$f{竹叶石膏汤}主之。', '2024-12-16T09:13:13.000Z', 1, NULL, '5IGM9t76quT', 'section', 'kBNKud90m4z');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('7qNqZCJFggU', 4, '{"title":"21","description":"<p>21、大病已解，而日暮微烦者，以病新差，人强与谷，脾胃之气尚弱，不能消谷，故令微烦，损谷则愈。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002421,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-16T09:13:13.000Z', '2024-12-16T09:13:13.000Z', '2024-12-16T09:13:13.000Z', '21、大病已解，而日暮微烦者，以病新差，人强与谷，脾胃之气尚弱，不能消谷，故令微烦，损谷则愈。', '2024-12-16T09:13:13.000Z', 1, NULL, '5IGM9t76quT', 'section', 'kBNKud90m4z');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('5Yx8sMC4Nq9', 4, '{"title":"1","description":"<p>1、百合病者，百脉一宗，悉致其病也，意欲食，复不能食，常默默，欲卧不能卧，欲行不能行，饮食或有美时，或有不欲闻食臭时，如寒无寒，如热无热，口苦，小便赤，诸药不能治，得药则剧吐利，如有神灵者，身形如和，其脉微数，每溺时头痛者，六十日乃愈。若溺时头不痛，淅淅然者，四十日愈。若溺时快然，但头眩者，二十日愈。其证或未病而预见，或病四五日始见，或病至二十日，或一月后见者；各随其证，依法治之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002501,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-16T09:35:50.000Z', '2024-12-16T09:35:50.000Z', '2024-12-16T09:35:50.000Z', '1、百合病者，百脉一宗，悉致其病也，意欲食，复不能食，常默默，欲卧不能卧，欲行不能行，饮食或有美时，或有不欲闻食臭时，如寒无寒，如热无热，口苦，小便赤，诸药不能治，得药则剧吐利，如有神灵者，身形如和，其脉微数，每溺时头痛者，六十日乃愈。若溺时头不痛，淅淅然者，四十日愈。若溺时快然，但头眩者，二十日愈。其证或未病而预见，或病四五日始见，或病至二十日，或一月后见者；各随其证，依法治之。', '2024-12-16T09:35:50.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Ay62bNVdQvD');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('flJ1j3Vp6zc', 4, '{"title":"2、百合病，见于发汗之后者，$f{百合知母汤}主之","description":"<p>2、百合病，见于发汗之后者，$f{百合知母汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002502,"note":"","videoMemo":"","fangList":["百合知母汤"],"bieMing":""}}', '2024-12-16T09:35:50.000Z', '2024-12-16T09:35:50.000Z', '2024-12-16T09:35:50.000Z', '2、百合病，见于发汗之后者，$f{百合知母汤}主之。', '2024-12-16T09:35:50.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Ay62bNVdQvD');
