INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('YMlw5kHPfSR', 4, '{"title":"6","description":"<p>6、百合病，一月不解，变成渴者，$f{百合洗方主}之；不差，$f{括蒌牡蛎散}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002506,"note":"","videoMemo":"","fangList":["百合洗方主","括蒌牡蛎散"],"bieMing":""}}', '2024-12-16T09:35:50.000Z', '2024-12-16T09:35:50.000Z', '2024-12-16T09:35:50.000Z', '6、百合病，一月不解，变成渴者，$f{百合洗方主}之；不差，$f{括蒌牡蛎散}主之。', '2024-12-16T09:35:50.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Ay62bNVdQvD');
