INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('fqaTkaseAGQ', 4, '{"title":"8","description":"<p>8、百合病，见于阴者，以阳法救之；见于阳者，以阴法救之；见阳攻阴，复发其汗，此为逆，见阴攻阳，乃复下之，此亦为逆。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002508,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-16T09:35:50.000Z', '2024-12-16T09:35:50.000Z', '2024-12-16T09:35:50.000Z', '8、百合病，见于阴者，以阳法救之；见于阳者，以阴法救之；见阳攻阴，复发其汗，此为逆，见阴攻阳，乃复下之，此亦为逆。', '2024-12-16T09:35:50.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Ay62bNVdQvD');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('NYaUAyvhBwe', 4, '{"title":"9、狐惑之为病，状如伤寒，默默欲眠，目不得闭，卧起不安","description":"<p>9、狐惑之为病，状如伤寒，默默欲眠，目不得闭，卧起不安。蚀于喉为惑，蚀于阴为狐，不欲饮食，恶闻食臭，其面目乍赤，乍黑，乍白，蚀于上部则声嗄，$f{甘草泻心汤}主之；蚀于下部则咽干，$f{苦参汤}洗之；蚀于肛者，$u{雄黄}薰之。 </p>\n<p>    </p>\n<p>另：$a{雄黄}应该是$f{雄黄散}</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002509,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-16T09:35:50.000Z', '2024-12-16T09:35:50.000Z', '2024-12-16T09:35:50.000Z', '9、狐惑之为病，状如伤寒，默默欲眠，目不得闭，卧起不安。蚀于喉为惑，蚀于阴为狐，不欲饮食，恶闻食臭，其面目乍赤，乍黑，乍白，蚀于上部则声嗄，$f{甘草泻心汤}主之；蚀于下部则咽干，$f{苦参汤}洗之；蚀于肛者，$u{雄黄}薰之。 另：$a{雄黄}应该是$f{雄黄散}', '2024-12-16T09:35:50.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Ay62bNVdQvD');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('LxsFr9k9wGu', 4, '{"title":"10","description":"<p>10、病者脉数，无热微烦，默默但欲卧，汗出，初得之三四日，目赤如鸠眼，七八日，目四眦黑，若能食者，脓已成也，$f{赤豆当归散}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002510,"note":"","videoMemo":"","fangList":["赤豆当归散"],"bieMing":""}}', '2024-12-16T09:35:50.000Z', '2024-12-16T09:35:50.000Z', '2024-12-16T09:35:50.000Z', '10、病者脉数，无热微烦，默默但欲卧，汗出，初得之三四日，目赤如鸠眼，七八日，目四眦黑，若能食者，脓已成也，$f{赤豆当归散}主之。', '2024-12-16T09:35:50.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Ay62bNVdQvD');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('UDP1qT25Sm2', 4, '{"title":"11","description":"<p>11、阳毒之为病，面赤斑斑如锦纹，咽喉痛，唾脓血，五日可治，七日不可治，$f{升麻鳖甲汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002511,"note":"","videoMemo":"","fangList":["升麻鳖甲汤"],"bieMing":""}}', '2024-12-16T09:35:50.000Z', '2024-12-16T09:35:50.000Z', '2024-12-16T09:35:50.000Z', '11、阳毒之为病，面赤斑斑如锦纹，咽喉痛，唾脓血，五日可治，七日不可治，$f{升麻鳖甲汤}主之。', '2024-12-16T09:35:50.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Ay62bNVdQvD');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('O9hncOJsVsI', 4, '{"title":"12","description":"<p>12、阴毒之为病，面目青，身痛如被杖，咽喉痛，五日可治；七日不可治；$f{升麻鳖甲汤去雄黄蜀椒}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002512,"note":"","videoMemo":"","fangList":["升麻鳖甲汤去雄黄蜀椒"],"bieMing":""}}', '2024-12-16T09:35:50.000Z', '2024-12-16T09:35:50.000Z', '2024-12-16T09:35:50.000Z', '12、阴毒之为病，面目青，身痛如被杖，咽喉痛，五日可治；七日不可治；$f{升麻鳖甲汤去雄黄蜀椒}主之。', '2024-12-16T09:35:50.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Ay62bNVdQvD');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('fCeRGdS57IG', 4, '{"title":"1","description":"<p>1、师曰：疟病其脉弦数者，热多寒少；</p>\n<p>                其脉弦迟者，寒多热少。</p>\n<p>                脉弦而小紧者，可下之；</p>\n<p>                弦迟者，可温之，</p>\n<p>                弦紧者，可汗之，针之，灸之；</p>\n<p>                浮大者，可吐之；</p>\n<p>                弦数者，风发也，当于少阳中求之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002513,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-17T00:53:18.000Z', '2024-12-17T00:53:18.000Z', '2024-12-17T00:53:18.000Z', '1、师曰：疟病其脉弦数者，热多寒少； 其脉弦迟者，寒多热少。 脉弦而小紧者，可下之； 弦迟者，可温之， 弦紧者，可汗之，针之，灸之； 浮大者，可吐之； 弦数者，风发也，当于少阳中求之。', '2024-12-17T00:53:18.000Z', 1, NULL, '5IGM9t76quT', 'section', 'N18NIzeqEiz');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('O6lfluYKhSq', 4, '{"title":"2","description":"<p>2、问曰：疟病以月一发者，当以十五日愈，甚者当月尽解，如其不差，当云何?</p>\n<p></p>\n<p>           师曰：此结为症瘕，必有疟母，急治之，宜鳖甲煎丸。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002514,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-17T00:53:18.000Z', '2024-12-17T00:53:18.000Z', '2024-12-17T00:53:18.000Z', '2、问曰：疟病以月一发者，当以十五日愈，甚者当月尽解，如其不差，当云何? 师曰：此结为症瘕，必有疟母，急治之，宜鳖甲煎丸。', '2024-12-17T00:53:18.000Z', 1, NULL, '5IGM9t76quT', 'section', 'N18NIzeqEiz');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('2NN7e3tjACu', 4, '{"title":"3","description":"<p>3、师曰：阴气孤绝，阳气独发，则热而少气烦悗，手足热而欲呕，此名疸疟，$f{白虎加桂枝人参汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002515,"note":"","videoMemo":"","fangList":["白虎加桂枝人参汤"],"bieMing":""}}', '2024-12-17T00:53:18.000Z', '2024-12-17T00:53:18.000Z', '2024-12-17T00:53:18.000Z', '3、师曰：阴气孤绝，阳气独发，则热而少气烦悗，手足热而欲呕，此名疸疟，$f{白虎加桂枝人参汤}主之。', '2024-12-17T00:53:18.000Z', 1, NULL, '5IGM9t76quT', 'section', 'N18NIzeqEiz');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('4LV8OGtkhas', 4, '{"title":"4","description":"<p>4、疟病，其脉如平，身无寒，但热，骨节疼烦，时作呕，此名温疟，宜$f{白虎加桂枝汤}。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002516,"note":"","videoMemo":"","fangList":["白虎加桂枝汤"],"bieMing":""}}', '2024-12-17T00:53:18.000Z', '2024-12-17T00:53:18.000Z', '2024-12-17T00:53:18.000Z', '4、疟病，其脉如平，身无寒，但热，骨节疼烦，时作呕，此名温疟，宜$f{白虎加桂枝汤}。', '2024-12-17T00:53:18.000Z', 1, NULL, '5IGM9t76quT', 'section', 'N18NIzeqEiz');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('j5aUyVzQqr9', 4, '{"title":"5","description":"<p>5、疟病，多寒，或但寒不热者，此名牡疟，$f{蜀漆散}主之，$f{柴胡桂姜汤}亦主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002517,"note":"","videoMemo":"","fangList":["蜀漆散","柴胡桂姜汤"],"bieMing":""}}', '2024-12-17T00:53:18.000Z', '2024-12-17T00:53:18.000Z', '2024-12-17T00:53:18.000Z', '5、疟病，多寒，或但寒不热者，此名牡疟，$f{蜀漆散}主之，$f{柴胡桂姜汤}亦主之。', '2024-12-17T00:53:18.000Z', 1, NULL, '5IGM9t76quT', 'section', 'N18NIzeqEiz');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('eeiR7yLftz5', 4, '{"title":"1","description":"<p>1、问曰：血痹之病，从何得之？</p>\n<p></p>\n<p>          师曰：夫尊荣之人，骨弱，肌肤盛，重因疲劳，汗出，卧不时动摇，加被微风，遂得之。但以脉寸口微涩，关上小紧，宜针引阳气，令脉和，紧去则愈。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002701,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-17T02:14:25.000Z', '2024-12-17T02:14:25.000Z', '2024-12-17T02:14:25.000Z', '1、问曰：血痹之病，从何得之？ 师曰：夫尊荣之人，骨弱，肌肤盛，重因疲劳，汗出，卧不时动摇，加被微风，遂得之。但以脉寸口微涩，关上小紧，宜针引阳气，令脉和，紧去则愈。', '2024-12-17T02:14:25.000Z', 1, NULL, '5IGM9t76quT', 'section', 'PyUWgHiFRAt');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('U9gE15tHzVq', 4, '{"title":"2","description":"<p>2、血痹，阴阳俱微，或寸口关上微，尺中小紧，外证身体不仁，如风痹状，$f{黄芪桂枝五物汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002702,"note":"","videoMemo":"","fangList":["黄芪桂枝五物汤"],"bieMing":""}}', '2024-12-17T02:14:25.000Z', '2024-12-17T02:14:25.000Z', '2024-12-17T02:14:25.000Z', '2、血痹，阴阳俱微，或寸口关上微，尺中小紧，外证身体不仁，如风痹状，$f{黄芪桂枝五物汤}主之。', '2024-12-17T02:14:25.000Z', 1, NULL, '5IGM9t76quT', 'section', 'PyUWgHiFRAt');
