INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('5WFQAsDBuaY', 4, '{"title":"5","description":"<p>5、男子脉虚沉弦，无寒热，短气，里急，小便不利，面色白，时目瞑兼衄，少腹满，此为劳使之然。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002705,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-17T02:14:25.000Z', '2024-12-17T02:14:25.000Z', '2024-12-17T02:14:25.000Z', '5、男子脉虚沉弦，无寒热，短气，里急，小便不利，面色白，时目瞑兼衄，少腹满，此为劳使之然。', '2024-12-17T02:14:25.000Z', 1, NULL, '5IGM9t76quT', 'section', 'PyUWgHiFRAt');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('0PdLVn7pagL', 4, '{"title":"6","description":"<p>6、劳之为病，其脉浮大，手足烦，春夏剧，秋冬差，阴寒精自出，酸削不能行。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002706,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-17T02:14:25.000Z', '2024-12-17T02:14:25.000Z', '2024-12-17T02:14:25.000Z', '6、劳之为病，其脉浮大，手足烦，春夏剧，秋冬差，阴寒精自出，酸削不能行。', '2024-12-17T02:14:25.000Z', 1, NULL, '5IGM9t76quT', 'section', 'PyUWgHiFRAt');
