INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('m6Ub7wHlOmw', 4, '{"title":"8","description":"<p>8、失精家，少阴脉弦急，阴头寒，目眩，发落，脉极虚芤迟者，为清谷亡血失精；脉得诸芤动微紧者，男子则失精，女子则梦交，$f{桂枝龙骨牡蛎汤}主之。$f{天雄散}亦主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002708,"note":"","videoMemo":"","fangList":["桂枝龙骨牡蛎汤","天雄散"],"bieMing":""}}', '2024-12-17T02:14:25.000Z', '2024-12-17T02:14:25.000Z', '2024-12-17T02:14:25.000Z', '8、失精家，少阴脉弦急，阴头寒，目眩，发落，脉极虚芤迟者，为清谷亡血失精；脉得诸芤动微紧者，男子则失精，女子则梦交，$f{桂枝龙骨牡蛎汤}主之。$f{天雄散}亦主之。', '2024-12-17T02:14:25.000Z', 1, NULL, '5IGM9t76quT', 'section', 'PyUWgHiFRAt');
