INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('74Pq35TaZFz', 4, '{"title":"10","description":"<p>10、人年五六十，其脉大者，病痹，挟背行；若肠鸣，马刀挟瘿者，皆为劳得之也。其脉小沉迟者，病脱气，疾行则喘渴；手足逆寒者，亦劳之为病也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002710,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-17T02:14:25.000Z', '2024-12-17T02:14:25.000Z', '2024-12-17T02:14:25.000Z', '10、人年五六十，其脉大者，病痹，挟背行；若肠鸣，马刀挟瘿者，皆为劳得之也。其脉小沉迟者，病脱气，疾行则喘渴；手足逆寒者，亦劳之为病也。', '2024-12-17T02:14:25.000Z', 1, NULL, '5IGM9t76quT', 'section', 'PyUWgHiFRAt');
