INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('j7ma4mGPl53', 4, '{"title":"15","description":"<p>15、五劳虚极，赢瘦腹满，不能饮食，食伤，忧伤，饮伤，房室伤，饥伤，劳伤，经络荣卫气伤，内有干血，肌肤甲错，两目黯黑，缓中补虚，$f{大黄䗪虫丸}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002715,"note":"","videoMemo":"","fangList":["大黄䗪虫丸"],"bieMing":""}}', '2024-12-17T02:14:25.000Z', '2024-12-17T02:14:25.000Z', '2024-12-17T02:14:25.000Z', '15、五劳虚极，赢瘦腹满，不能饮食，食伤，忧伤，饮伤，房室伤，饥伤，劳伤，经络荣卫气伤，内有干血，肌肤甲错，两目黯黑，缓中补虚，$f{大黄䗪虫丸}主之。', '2024-12-17T02:14:25.000Z', 1, NULL, '5IGM9t76quT', 'section', 'PyUWgHiFRAt');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('e0vh8UUNRm2', 4, '{"title":"16","description":"<p>16、女劳，膀胱急，少腹满，身尽黄，额上黑，足下热，其腹胀如水状，大便溏而黑，胸满者，难治，$f{硝石矾石散}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002716,"note":"","videoMemo":"","fangList":["硝石矾石散"],"bieMing":""}}', '2024-12-17T02:14:25.000Z', '2024-12-17T02:14:25.000Z', '2024-12-17T02:14:25.000Z', '16、女劳，膀胱急，少腹满，身尽黄，额上黑，足下热，其腹胀如水状，大便溏而黑，胸满者，难治，$f{硝石矾石散}主之。', '2024-12-17T02:14:25.000Z', 1, NULL, '5IGM9t76quT', 'section', 'PyUWgHiFRAt');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('zh4IZ5rUs2t', 4, '{"title":"1","description":"<p>1、师曰：咳嗽发于肺，不专属于肺病也。五脏，六腑，感受客邪，皆能致咳。所以然者，邪气上逆，必干于肺，肺为气动，发声为咳，欲知其源，必察脉息，为子条记，传与后贤。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002801,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-17T05:29:29.000Z', '2024-12-17T05:29:29.000Z', '2024-12-17T05:29:29.000Z', '1、师曰：咳嗽发于肺，不专属于肺病也。五脏，六腑，感受客邪，皆能致咳。所以然者，邪气上逆，必干于肺，肺为气动，发声为咳，欲知其源，必察脉息，为子条记，传与后贤。', '2024-12-17T05:29:29.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Z8BIBJV0eq2');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('VQoHExIuf68', 4, '{"title":"2、肺咳，脉短而涩","description":"<p>2、肺咳，脉短而涩。假令浮而涩，知受风邪；紧短而涩，知受寒邪；数短而涩，知受热邪；急短而涩，知受燥邪；濡短而涩，知受湿邪。此肺咳之因也。其状则喘息有音，甚则唾血。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002802,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-17T05:29:29.000Z', '2024-12-17T05:29:29.000Z', '2024-12-17T05:29:29.000Z', '2、肺咳，脉短而涩。假令浮而涩，知受风邪；紧短而涩，知受寒邪；数短而涩，知受热邪；急短而涩，知受燥邪；濡短而涩，知受湿邪。此肺咳之因也。其状则喘息有音，甚则唾血。', '2024-12-17T05:29:29.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Z8BIBJV0eq2');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Y5Dw6Zuhwws', 4, '{"title":"3、心咳，脉大而散","description":"<p>3、心咳，脉大而散。假令浮大而散，知受风邪，紧大而散，知受寒邪；数大而散，知受热邪；急大而散，知受燥邪；濡大而散，知受湿邪；此心咳之因也。其状则心痛，喉中介介如梗，甚则咽肿，喉痹。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002803,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-17T05:29:29.000Z', '2024-12-17T05:29:29.000Z', '2024-12-17T05:29:29.000Z', '3、心咳，脉大而散。假令浮大而散，知受风邪，紧大而散，知受寒邪；数大而散，知受热邪；急大而散，知受燥邪；濡大而散，知受湿邪；此心咳之因也。其状则心痛，喉中介介如梗，甚则咽肿，喉痹。', '2024-12-17T05:29:29.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Z8BIBJV0eq2');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('GcXhxYoZcaA', 4, '{"title":"4、肝咳，脉弦而涩","description":"<p>4、肝咳，脉弦而涩。假令浮弦而涩，知受风邪；弦紧而涩，知受寒邪；弦数而涩，知受热邪；弦急而涩，知受燥邪；弦濡而涩，知受湿邪；此肝咳之因也。其状则两胁下痛，甚则不可以转，转则两胠下满。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002804,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-17T05:29:29.000Z', '2024-12-17T05:29:29.000Z', '2024-12-17T05:29:29.000Z', '4、肝咳，脉弦而涩。假令浮弦而涩，知受风邪；弦紧而涩，知受寒邪；弦数而涩，知受热邪；弦急而涩，知受燥邪；弦濡而涩，知受湿邪；此肝咳之因也。其状则两胁下痛，甚则不可以转，转则两胠下满。', '2024-12-17T05:29:29.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Z8BIBJV0eq2');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('1tGbKZ7A9i0', 4, '{"title":"5、脾咳，脉濡而涩","description":"<p>5、脾咳，脉濡而涩。假令浮濡而涩，知受风邪；沉濡而涩，知受寒邪；数濡而涩，知受热邪；急濡而涩，知受燥邪；迟濡而涩，知受湿邪；此脾咳之因也。其状则右肋下痛，隐隐引背，甚则不可以动，动则咳剧。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002805,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-17T05:29:29.000Z', '2024-12-17T05:29:29.000Z', '2024-12-17T05:29:29.000Z', '5、脾咳，脉濡而涩。假令浮濡而涩，知受风邪；沉濡而涩，知受寒邪；数濡而涩，知受热邪；急濡而涩，知受燥邪；迟濡而涩，知受湿邪；此脾咳之因也。其状则右肋下痛，隐隐引背，甚则不可以动，动则咳剧。', '2024-12-17T05:29:29.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Z8BIBJV0eq2');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('bs4Z9u27K0N', 4, '{"title":"6、肾咳，脉沉而濡","description":"<p>6、肾咳，脉沉而濡。假令沉弦而濡，知受风邪；沉紧而濡，知受寒邪；沉数而濡，知受热邪；沉急而濡，知受燥邪；沉滞而濡，知受湿邪；此肾咳之因也。其状则肩背相引而痛，甚则咳涎。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002806,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-17T05:29:29.000Z', '2024-12-17T05:29:29.000Z', '2024-12-17T05:29:29.000Z', '6、肾咳，脉沉而濡。假令沉弦而濡，知受风邪；沉紧而濡，知受寒邪；沉数而濡，知受热邪；沉急而濡，知受燥邪；沉滞而濡，知受湿邪；此肾咳之因也。其状则肩背相引而痛，甚则咳涎。', '2024-12-17T05:29:29.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Z8BIBJV0eq2');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Um55BDIs75a', 4, '{"title":"7、肺咳不已，则流于大肠，脉与肺同，其状则咳而遗矢也","description":"<p>7、肺咳不已，则流于大肠，脉与肺同，其状则咳而遗矢也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002807,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-17T05:29:29.000Z', '2024-12-17T05:29:29.000Z', '2024-12-17T05:29:29.000Z', '7、肺咳不已，则流于大肠，脉与肺同，其状则咳而遗矢也。', '2024-12-17T05:29:29.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Z8BIBJV0eq2');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('2w2sDbnTbbZ', 4, '{"title":"8","description":"<p>8、心咳不已，则流于小肠，脉与心同，其状则咳而失气，气与咳俱失也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002808,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-17T05:29:29.000Z', '2024-12-17T05:29:29.000Z', '2024-12-17T05:29:29.000Z', '8、心咳不已，则流于小肠，脉与心同，其状则咳而失气，气与咳俱失也。', '2024-12-17T05:29:29.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Z8BIBJV0eq2');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('W3b8476taqx', 4, '{"title":"9、肝咳不已，则流于胆，脉与肝同，其状则呕苦汁也","description":"<p>9、肝咳不已，则流于胆，脉与肝同，其状则呕苦汁也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002809,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-17T05:29:29.000Z', '2024-12-17T05:29:29.000Z', '2024-12-17T05:29:29.000Z', '9、肝咳不已，则流于胆，脉与肝同，其状则呕苦汁也。', '2024-12-17T05:29:29.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Z8BIBJV0eq2');
