INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('fulIE6SCNMM', 4, '{"title":"12","description":"<p>12、久咳不已，则移于三焦，脉随证易，其状则咳而腹满，不欲食饮也。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002812,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-17T05:29:29.000Z', '2024-12-17T05:29:29.000Z', '2024-12-17T05:29:29.000Z', '12、久咳不已，则移于三焦，脉随证易，其状则咳而腹满，不欲食饮也。', '2024-12-17T05:29:29.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Z8BIBJV0eq2');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Ilw4oznCJyc', 4, '{"title":"13","description":"<p>13、咳而有饮者，咳不得卧，卧则气急，此为实咳，不能言，言则气短，此为虚咳，病多端，治各异法，谨守其道，庶可万全。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002813,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-17T05:29:29.000Z', '2024-12-17T05:29:29.000Z', '2024-12-17T05:29:29.000Z', '13、咳而有饮者，咳不得卧，卧则气急，此为实咳，不能言，言则气短，此为虚咳，病多端，治各异法，谨守其道，庶可万全。', '2024-12-17T05:29:29.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Z8BIBJV0eq2');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('QBMGHXzhRI5', 4, '{"title":"14、咳家其脉弦者，此为有水，$f{十枣汤}主之","description":"<p>14、咳家其脉弦者，此为有水，$f{十枣汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002814,"note":"","videoMemo":"","fangList":["十枣汤"],"bieMing":""}}', '2024-12-17T05:29:29.000Z', '2024-12-17T05:29:29.000Z', '2024-12-17T05:29:29.000Z', '14、咳家其脉弦者，此为有水，$f{十枣汤}主之。', '2024-12-17T05:29:29.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Z8BIBJV0eq2');
