INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('AFVEOLyVay6', 4, '{"title":"21","description":"<p>21、咳而胸满，振寒脉数，咽干不渴，时出浊唾腥臭，久久吐脓，如米粥者，此为肺痈，$f{桔梗汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002821,"note":"","videoMemo":"","fangList":["桔梗汤"],"bieMing":""}}', '2024-12-17T05:29:29.000Z', '2024-12-17T05:29:29.000Z', '2024-12-17T05:29:29.000Z', '21、咳而胸满，振寒脉数，咽干不渴，时出浊唾腥臭，久久吐脓，如米粥者，此为肺痈，$f{桔梗汤}主之。', '2024-12-17T05:29:29.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Z8BIBJV0eq2');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('xr1pMWBF9AC', 4, '{"title":"22","description":"<p>22、咳而气喘，目如脱状，脉浮大者，此为肺胀，$f{越婢加半夏汤}主之；$f{小青龙加石膏汤}亦主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002822,"note":"","videoMemo":"","fangList":["越婢加半夏汤","小青龙加石膏汤"],"bieMing":""}}', '2024-12-17T05:29:29.000Z', '2024-12-17T05:29:29.000Z', '2024-12-17T05:29:29.000Z', '22、咳而气喘，目如脱状，脉浮大者，此为肺胀，$f{越婢加半夏汤}主之；$f{小青龙加石膏汤}亦主之。', '2024-12-17T05:29:29.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Z8BIBJV0eq2');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('kGGheGUKwk2', 4, '{"title":"23","description":"<p>23、咳而气逆，喘鸣，迫塞胸满而胀，一身面目浮肿，鼻出清涕，不闻香臭，此为肺胀，$f{葶苈大枣泻肺汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002823,"note":"","videoMemo":"","fangList":["葶苈大枣泻肺汤"],"bieMing":""}}', '2024-12-17T05:29:29.000Z', '2024-12-17T05:29:29.000Z', '2024-12-17T05:29:29.000Z', '23、咳而气逆，喘鸣，迫塞胸满而胀，一身面目浮肿，鼻出清涕，不闻香臭，此为肺胀，$f{葶苈大枣泻肺汤}主之。', '2024-12-17T05:29:29.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Z8BIBJV0eq2');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Fr2CGvND84g', 4, '{"title":"24","description":"<p>24、似咳非咳，唾多涎沫，其人不渴，此为肺冷，$f{甘草干姜汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002824,"note":"","videoMemo":"","fangList":["甘草干姜汤"],"bieMing":""}}', '2024-12-17T05:29:29.000Z', '2024-12-17T05:29:29.000Z', '2024-12-17T05:29:29.000Z', '24、似咳非咳，唾多涎沫，其人不渴，此为肺冷，$f{甘草干姜汤}主之。', '2024-12-17T05:29:29.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Z8BIBJV0eq2');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('yJSF4o3UsV5', 4, '{"title":"25","description":"<p>25、咳而唾涎沫不止，咽燥，口渴，其脉浮细而数者，此为肺痿，$f{炙甘草汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002825,"note":"","videoMemo":"","fangList":["炙甘草汤"],"bieMing":""}}', '2024-12-17T05:29:29.000Z', '2024-12-17T05:29:29.000Z', '2024-12-17T05:29:29.000Z', '25、咳而唾涎沫不止，咽燥，口渴，其脉浮细而数者，此为肺痿，$f{炙甘草汤}主之。', '2024-12-17T05:29:29.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Z8BIBJV0eq2');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('werWVEVXWmg', 4, '{"title":"26","description":"<p>26、问曰：饮病奈何？师曰：饮病有四：曰痰饮，曰悬饮，曰溢饮，曰支饮。其人素盛今瘦，水走肠间，沥沥有声，为痰饮，水流胁下，咳唾引痛，为悬饮；水归四肢，当汗不汗，身体疼重，为溢饮；水停膈下，咳逆倚息，短气不得卧，其形如肿，为支饮。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002826,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-17T05:29:29.000Z', '2024-12-17T05:29:29.000Z', '2024-12-17T05:29:29.000Z', '26、问曰：饮病奈何？师曰：饮病有四：曰痰饮，曰悬饮，曰溢饮，曰支饮。其人素盛今瘦，水走肠间，沥沥有声，为痰饮，水流胁下，咳唾引痛，为悬饮；水归四肢，当汗不汗，身体疼重，为溢饮；水停膈下，咳逆倚息，短气不得卧，其形如肿，为支饮。', '2024-12-17T05:29:29.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Z8BIBJV0eq2');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('QR3sQq0hfn7', 4, '{"title":"27","description":"<p>27、水在心，则心下坚筑，短气，恶水不欲饮；水在肺，必吐涎沫，欲饮水；水在脾，则少气身重；水在肝，则胁下支满，嚏则胁痛；水在肾，则心下悸。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002827,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-17T05:29:29.000Z', '2024-12-17T05:29:29.000Z', '2024-12-17T05:29:29.000Z', '27、水在心，则心下坚筑，短气，恶水不欲饮；水在肺，必吐涎沫，欲饮水；水在脾，则少气身重；水在肝，则胁下支满，嚏则胁痛；水在肾，则心下悸。', '2024-12-17T05:29:29.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Z8BIBJV0eq2');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('BBRAvv6QSzJ', 4, '{"title":"28、心下有留饮，其人必背寒冷如掌大，咳则肋下痛引缺盆","description":"<p>28、心下有留饮，其人必背寒冷如掌大，咳则肋下痛引缺盆。</p>","content_format":"html","_microfeed":{"bookId":"5IGM9t76quT","receiptNo":1001002828,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-12-17T05:29:29.000Z', '2024-12-17T05:29:29.000Z', '2024-12-17T05:29:29.000Z', '28、心下有留饮，其人必背寒冷如掌大，咳则肋下痛引缺盆。', '2024-12-17T05:29:29.000Z', 1, NULL, '5IGM9t76quT', 'section', 'Z8BIBJV0eq2');
